#!/data/data/com.termux/files/usr/bin/bash
# HAYU - Halaman Pengaturan: email & Keluar dipindah dari Profil ke Pengaturan
# Syarat: profil baru (pasang-profil.sh) sudah terpasang.
# Jalankan di root repo:  bash pasang-pengaturan.sh
set -e
cd "${REPO:-$PWD}"
D="app/src/main/java/com/hayu/app"
[ -f "$D/ProfileTheme.kt" ] || { echo "❌ Pasang dulu profil baru (pasang-profil.sh)"; exit 1; }
M="app/src/main/AndroidManifest.xml"
T="$(mktemp -d)"
cat > "$T/b.b64" <<'B64_EOF'

B64_EOF
base64 -d "$T/b.b64" > "$T/b.tgz"
mkdir "$T/new" && tar xzf "$T/b.tgz" -C "$T/new"
BK="$HOME/.hayu-backup-set-$(date +%H%M%S)"
FIXED=0
fix() {
  f="$1"; m="$2"
  if [ -f "$f" ] && grep -q -- "$m" "$f"; then
    echo "  ok         $f"
  else
    [ -f "$f" ] && { mkdir -p "$BK/$(dirname "$f")"; cp "$f" "$BK/$f"; }
    cp "$T/new/$f" "$f"
    echo "  DIPERBAIKI $f"
    FIXED=$((FIXED+1))
  fi
}
fix $D/SettingsActivity.kt                        "class SettingsActivity"
fix $D/ProfileFragment.kt                         "SettingsActivity::class"
fix app/src/main/res/layout/fragment_profile.xml  "email & keluar ada di Pengaturan"
if grep -q "SettingsActivity" "$M"; then
  echo "  ok         $M"
else
  mkdir -p "$BK/app/src/main"; cp "$M" "$BK/$M"
  sed -i 's#^    </application>#        <activity\n            android:name=".SettingsActivity"\n            android:exported="false"\n            android:screenOrientation="portrait" />\n    </application>#' "$M"
  grep -q "SettingsActivity" "$M" || { echo "❌ Gagal mendaftarkan SettingsActivity di Manifest"; exit 1; }
  echo "  DIPERBAIKI $M"
  FIXED=$((FIXED+1))
fi
rm -rf "$T"
[ "$FIXED" -eq 0 ] && echo "✅ Sudah terpasang, tidak ada yang diubah." || echo "✅ $FIXED file dipasang (backup lama: $BK)"
if [ -d .git ] && [ "$FIXED" -gt 0 ]; then
  BR=$(git rev-parse --abbrev-ref HEAD)
  git add -A
  git commit -m "pengaturan: email & keluar dipindah dari profil" || true
  git pull --rebase --autostash origin "$BR" || { echo "⚠️ Konflik saat pull, selesaikan lalu: git rebase --continue && git push origin $BR"; exit 1; }
  git push origin "$BR"
  echo "✅ Terkirim ke origin/$BR"
fi
